def is_palindrome(text):
    cleaned_text = ""
    for i, char in enumerate(text):
        if char.isalnum():
            cleaned_text += char.lower()

    n = len(cleaned_text)
    for j, char_from_start in enumerate(cleaned_text):
        if j >= n // 2:
            break

        char_from_end = cleaned_text[n - 1 - j]
        if char_from_start != char_from_end:
            return False

    return True

