def validate_email(email):
    if not isinstance(email, str):
        return False

    at_index = -1
    dot_index = -1

    for i, char in enumerate(email):
        if char == '@':
            at_index = i
        if char == '.':
            dot_index = i

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    if at_index == 0 or dot_index == len(email) - 1:
        return False

    domain_part = email[at_index + 1 : dot_index]
    if not domain_part:
        return False

    for i, char in enumerate(domain_part):
        if not (char.isalnum() or char == '-'):
            return False

    local_part = email[:at_index]
    if not local_part:
        return False

    for i, char in enumerate(local_part):
        if not (char.isalnum() or char in ['.', '_', '-']):
            return False

    return True

