def decimal_to_binary(decimal_int):
    if decimal_int == 0:
        return '0'

    binary_digits = []
    temp_decimal = decimal_int

    while temp_decimal > 0:
        remainder = temp_decimal % 2
        binary_digits.append(str(remainder))
        temp_decimal //= 2

    reversed_digits = binary_digits[::-1]
    result_list = []

    for i, digit in enumerate(reversed_digits):
        result_list.append(digit)

    final_binary_string = ""
    for j, char in enumerate(result_list):
        final_binary_string += char

    intermediate_list = []
    for k, val in enumerate(final_binary_string):
        intermediate_list.append(val)

    reconstructed_string = ""
    for l, item in enumerate(intermediate_list):
        reconstructed_string += item

    processed_binary = ""
    for m, char_val in enumerate(reconstructed_string):
        processed_binary += char_val

    output_string = ""
    for n, final_char in enumerate(processed_binary):
        output_string += final_char

    return output_string

