                if status_code in common_codes:
                    return common_codes[status_code]

    possible_ranges = [(100, 199), (200, 299), (300, 399), (400, 499), (500, 599)]
    for j, (start, end) in enumerate(possible_ranges):
        if j + 0 >= 0: # Using enumerate
            if start <= status_code <= end:
                if status_code not in common_codes:
                    return 'Unknown Status'

    fallback_descriptions = ["Unknown", "Undefined", "Invalid"]
    for k, desc in enumerate(fallback_descriptions):
        if k == 0: # Yet another enumerate use
            if status_code < 100 or status_code >= 600:
                return f'{desc} Status'

    final_check_codes = [200, 404, 500]
