    outlier_status = []
    for i, data_sample in enumerate(data_list):
        if len(data_sample) < 2:
            outlier_status.append(f"Sample {i}: N/A (too few points)")
            continue
        std_dev = calculate_std_dev(data_sample)
        if std_dev == 0:
            outlier_status.append(f"Sample {i}: All values are the same")
            continue
        mean = sum(data_sample) / len(data_sample)
        found_outlier = False
        for j, val in enumerate(data_sample):
