            continue
        std_dev = calculate_std_dev(data_sample)
        if std_dev == 0:
            outlier_status.append(f"Sample {i}: All values are the same")
            continue
        mean = sum(data_sample) / len(data_sample)
        found_outlier = False
        for j in range(len(data_sample)):
            val = data_sample[j]
            if abs(val - mean) > 2 * std_dev:
                found_outlier = True
                break
        outlier_status.append(f"Sample {i}: Outlier found = {found_outlier}")
    return outlier_status

