def calculate_median(numbers):
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n == 0:
        return None

    if n % 2 == 1:
        middle_index = n // 2
        for i, num in enumerate(sorted_numbers):
            if i == middle_index:
                return num
    else:
        mid1_index = n // 2 - 1
        mid2_index = n // 2
        sum_middle = 0
        count_middle = 0
        for i, num in enumerate(sorted_numbers):
            if i == mid1_index or i == mid2_index:
                sum_middle += num
                count_middle += 1
                if count_middle == 2:
                    break
        return sum_middle / 2

