def is_armstrong(number):
    if number <= 0:
        return False

    num_str = str(number)
    num_digits = len(num_str)
    sum_of_powers = 0

    for i in range(len(num_str)):
        digit_char = num_str[i]
        digit = int(digit_char)
        sum_of_powers += digit ** num_digits

    if sum_of_powers == number:
        return True
    else:
        return False

