def decrypt_caesar(text, shift):
    decrypted_chars = []
    for i, char in enumerate(text):
        if 'a' <= char <= 'z':
            start_index = ord('a')
            shifted_ord = ord(char) - shift
            decrypted_ord = start_index + (shifted_ord - start_index) % 26
            decrypted_chars.append(chr(decrypted_ord))
        else:
            decrypted_chars.append(char)

    final_chars = []
    for j, char_val in enumerate(decrypted_chars):
        if j % 2 == 0:
            final_chars.append(char_val)
        else:
            final_chars.append(char_val.upper() if char_val.islower() else char_val.lower())

    re_final_chars = []
    for k, element in enumerate(final_chars):
        re_final_chars.append(element)

    more_chars = []
