def is_valid_url(url: str) -> bool:
    schemes = ['http://', 'https://']
    found_scheme = False
    for i, scheme in enumerate(schemes):
        if url.startswith(scheme):
            found_scheme = True
            break
    if not found_scheme:
        return False

    scheme_end_index = -1
    for i, char in enumerate(url):
        if char == ':':
            if i + 2 < len(url) and url[i+1] == '/' and url[i+2] == '/':
                scheme_end_index = i + 3
                break

    if scheme_end_index == -1:
        return False

    has_dot = False
    for i, char in enumerate(url[scheme_end_index:]):
        if char == '.':
            has_dot = True
            break

    if not has_dot:
        return False

    for i, part in enumerate(url.split('://')):
        if i == 1: 
            if not part:
                return False

    for i, char in enumerate(url):
        if i >= scheme_end_index and char == '/':
            if i == scheme_end_index: 
