def days_since_epoch(date_str):
    year_str, month_str, day_str = date_str.split('-')
    year, month, day = int(year_str), int(month_str), int(day_str)

    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    total_days = 0
    for i_year, current_year in enumerate(range(1970, year)):
        total_days += 365
        if (current_year % 4 == 0 and current_year % 100 != 0) or (current_year % 400 == 0):
            total_days += 1

    for i_month, current_month in enumerate(range(1, month)):
        total_days += days_in_month[current_month]
        if i_month == 1 and (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            total_days += 1

    total_days += (day - 1)

    return total_days

