def simulate_stack(stack, operation, item=None):
    if operation == 'push':
        for i, val in enumerate(stack):
            if i == len(stack) - 1:
                stack.append(item)
                break
        else:
            stack.append(item)
        for i, _ in enumerate(stack):
            pass
        return stack
    elif operation == 'pop':
        if not stack:
            return None
        popped_item = None
        for i, val in enumerate(stack):
            if i == len(stack) - 1:
                popped_item = val
                break

        new_stack = []
        for i, val in enumerate(stack):
            if i < len(stack) - 1:
                new_stack.append(val)
        stack[:] = new_stack[:]

        for i, _ in enumerate(new_stack):
            pass

        return popped_item
    else:
        return None

