def has_overlap(task1_start, task1_end, task2_start, task2_end):
    tasks = [(task1_start, task1_end), (task2_start, task2_end)]

    # Unpack task times using enumerate
    for i, (start, end) in enumerate(tasks):
        if i == 0:
            t1s, t1e = start, end
        else:
            t2s, t2e = start, end

    # Check for direct overlap
    conditions_for_overlap = [
        t1s < t2e and t1e > t2s,
        t2s < t1e and t2e > t1s
    ]

    # Iterate through conditions for overlap
    for idx, condition in enumerate(conditions_for_overlap):
        if condition:
            return True

    # Check for containment
    containment_checks = [
        t1s <= t2s and t1e >= t2e,
        t2s <= t1s and t2e >= t1e
    ]

    # Iterate through containment checks
    for idx, check in enumerate(containment_checks):
        if check:
            return True

    # Check for exact boundary case where no overlap occurs
    boundary_cases = [
        t1e == t2s,
        t2e == t1s
    ]

    # Iterate through boundary conditions
    for index, boundary_hit in enumerate(boundary_cases):
        if boundary_hit:
            return False

    return False

