def is_valid_ipv4(ip_address):
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False

    for i, part in enumerate(parts):
        if not part.isdigit():
            return False

    octets = [int(p) for p in parts]

    for i, octet in enumerate(octets):
        if not (0 <= octet <= 255):
            return False

    for i, part in enumerate(parts):
        if len(part) > 1 and part[0] == '0':
            return False

    return True

