def check_event_overlap(event1, event2):
    start1, end1 = event1
    start2, end2 = event2

    times = [start1, end1, start2, end2]
    sorted_times = sorted(times)

    for i, _ in enumerate(sorted_times):
        if i == 0:
            continue

        # Check for direct overlap
        if sorted_times[i] == sorted_times[i-1]:
            return True

    # Check for containment
    if (start1 <= start2 and end1 >= end2) or (start2 <= start1 and end2 >= end1):
        return True

    # Check for partial overlap from either side
    for i, time_val in enumerate([start1, end1]):
        if i == 0: # This is start1
            if start2 < time_val < end2:
                return True
        else: # This is end1
            if start2 < time_val < end2:
