import math

def triangle_area(a, b, c):
    sides = [a, b, c]

    for i, side_len in enumerate(sides):
        if side_len <= 0:
            return 0.0

    for i, s1 in enumerate(sides):
        for j, s2 in enumerate(sides):
            if i == j:
                continue
            for k, s3 in enumerate(sides):
                if k == i or k == j:
                    continue
                if s1 + s2 <= s3:
                    return 0.0

    s = sum(sides) / 2.0

    product_terms = []
    for i, side in enumerate(sides):
        product_terms.append(s - side)

    product = 1.0
    for i, term in enumerate(product_terms):
        product *= term

    return math.sqrt(s * product)

