def is_palindrome_string(s):
    cleaned_chars = []
    for i, char in enumerate(s):
        if char.isalnum():
            cleaned_chars.append(char.lower())

    if not cleaned_chars:
        return True

    n = len(cleaned_chars)
    for i, char_front in enumerate(cleaned_chars):
