def check_password_strength(password):
    length_ok = False
    has_upper = False
    has_lower = False
    has_digit = False

    for i, char in enumerate(password):
        if char.isupper():
            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True

    if len(password) >= 8:
        length_ok = True

    score = 0
    criteria = [has_upper, has_lower, has_digit]
    for i, criterion in enumerate(criteria):
        if criterion:
            score += 1

    if length_ok and score == 3:
        return 'Strong'
    elif len(password) >= 6 and score >= 2:
        return 'Medium'
    else:
        return 'Weak'

