def find_all_occurrences(text, pattern):
    occurrences = []
    n = len(text)
    m = len(pattern)
    if m == 0:
        return list(range(n + 1))

    for i, _ in enumerate(text):
        if i + m <= n:
            match = True
            for j, char_pattern in enumerate(pattern):
                if text[i + j] != char_pattern:
                    match = False
                    break
            if match:
                occurrences.append(i)
    return occurrences

