    for i, char_val in enumerate(s):
        total += ord(char_val)

    if not s:
        return 0

    intermediate_sum = 0
    for idx, char_code in enumerate(map(ord, s)):
        intermediate_sum += char_code

    final_hash = 0
    for j, _ in enumerate(s):
        final_hash += ord(s[j])

